import 'wxt/browser';

declare module 'wxt/browser' {
    export interface WxtRuntime {
        getURL(path: string): string;
    }

    namespace Browser {
        // Firefox's `menus` API. Missing from the Chromium-derived base
        // types, which only know `contextMenus` — but `contextMenus` is
        // undefined in Firefox runtimes, so the extension must use
        // `browser.menus` here.
        namespace menus {
            interface CreateProperties {
                id?: string;
                parentId?: string;
                contexts?: string[];
                title?: string;
                type?: 'normal' | 'separator' | 'checkbox' | 'radio';
            }

            interface OnClickData {
                menuItemId: string | number;
                parentMenuItemId?: string | number;
                targetElementId?: number;
            }

            function create(
                createProperties: CreateProperties,
            ): Promise<string | number>;
            function remove(menuItemId: string): Promise<void>;
            function getTargetElement(
                targetElementId: number,
            ): Element | undefined;

            namespace onClicked {
                function addListener(
                    callback: (info: OnClickData, tab: tabs.Tab) => void,
                ): void;
                function removeListener(
                    callback: (info: OnClickData, tab: tabs.Tab) => void,
                ): void;
            }
        }
    }
}
declare global {
    interface NotificationEntry extends NotificationOptions {
        visible: boolean;
        id: string;
    }

    interface UpdateNotificationOptions extends NotificationOptions {
        id: string;
    }

    interface RemoveNotificationOptions {
        id: string;
    }

    interface NotificationOptions {
        /** Pre-assigned id; generated by the receiver when absent. */
        id?: string;
        level: NotificationLevel;
        title?: string;
        message: string;
    }

    type RuntimeMessage =
        | {
              type: 'notification';
              options: NotificationOptions;
          }
        | {
              type: 'update-notification';
              options: UpdateNotificationOptions;
          }
        | {
              type: 'remove-notification';
              options: RemoveNotificationOptions;
          };

    interface UploadLink {
        id: string;
        name: string;
        shortName: string;
        apiKey: string;
        hotkey: string[];
    }
}
